            <p><span class="label">Reorder Level:</span> {{ReorderLevel}}</p>
            <p><span class="label">Status:</span> {{Status}}</p>
        </div>

        <div class="btn-container">
            <a href="{{RecordLink}}" class="btn">View Inventory Part</a>
        </div>

        <p>Please take necessary action to replenish the stock.</p>
    </div>

    <div class="footer">
