INSERT INTO application.option_set (id, name, application_name, description, "values", is_active, created_at, created_by, updated_at, updated_by, display_name, columns, deleted_at, deleted_by) VALUES ('063e4f66-0429-456c-b429-b8172d460112', 'Tax Groups', 'SPACELINX', 'TG', '[{"name":"Out of scope","value":"0","description":"Supplies on which you don''t charge any GST or include them in the returns.","operator":"none"},{"name":"Non-GST Supply","value":"0","description":"Supplies which do not come under GST such as petroleum products and liquor.","operator":"none"},{"name":"GST0","value":"0","description":"","operator":"%"},{"name":"GST5","value":"5","description":"","operator":"%"},{"name":"GST12","value":"12","description":"","operator":"%"},{"name":"GST18 [18%]","value":"18","description":"","operator":"%"},{"name":"GST28","value":"28","description":"","operator":"%"},{"name":"Nominal Fee","value":"200","description":"","operator":"+"},{"name":"PCB Tax","value":"300","operator":"+","description":"Supplies which have a design board will be having a fixed tax amount."},{"name":"Tax Group Test","value":"44.07","operator":"%","description":"This Test is run using % with 44.07"},{"name":"SGST","value":"9","operator":"%","description":"State Tax"},{"name":"Test 250/-","value":"250","operator":"+","description":"Nothing"},{"name":"New Test 22.05","value":"22.05","operator":"%","description":"Test 22.05"},{"name":"Laptop Test 78.05%","value":"78.05","operator":"%","description":""},{"name":"BCD","value":"10","operator":"%","description":"For Connectors"},{"name":"53.2% Test","value":"53.2","operator":"%","description":""},{"name":"53.3% Test","value":"53.3","operator":"%","description":"Nothing but just test"}]', true, '2025-08-05 18:07:17.613727+00', 'system@spacelinx.local', '2025-08-18 12:35:43.816454+00', 'system@spacelinx.local', 'Tax Groups', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
