INSERT INTO application.option_set (id, name, application_name, description, "values", is_active, created_at, created_by, updated_at, updated_by, display_name, columns, deleted_at, deleted_by) VALUES ('4bd2b2bf-c4b7-4dd4-b438-ec4844c00f83', 'standard_terms_and_conditions', 'SPACELINX', 'Standard Terms and Conditions', '[{"name":"Standard Terms and Conditions","description":"1.Quotation should be sent in the email / sealed envelopes superscribing the Enquiry Number and date of opening.  2.Prices quoted should be on the basis of F.O.R. Hyderabad / delivery at site. The purchaser will not pay separately for transit insurance. All risks in transit shall be exclusively of the supplier, and the Purchaser shall pay only for such stores as are received in good condition in accordance with the contract.  3.Quotation should be valid for atleast 60 days from the date of opening of the tender  4.The time for the date of delivery of stores stipulated in the purchase order shall be deemed to be the essence of the contract and delivery must be completed not later than the date (s) specified therein. Failure to do so without adequate justification may involve cancellation of the contract/Order at the discretion of Purchaser.  5.a) Prices are required to be quoted according to the units indicated in the annexed tender Form / Mail. When quotations are given in terms of units other than those specified in the tender form, relationship between the two sets of units must be furnished.   b) Corrections, if any, must be attested. All amounts shall be indicated both in words as well as in figures. Where there is difference between the amount quoted in words and figures, amounts quoted in words shall prevail.  6.The Purchaser reserves the right to accept or reject any quotation fully or partly without assigning any reasons.  7.Payment terms are full payments within 30 days from the date of receipt and acceptance of material orders.  8.Late tenders will not be considered.  9.Where counter terms and conditions have been offered by the tenderer, the same shall not be deemed to have been accepted by the Purchaser. Unless the Purchaser’s specific written acceptance thereof is obtained.  10.SPECIFICATIONS: Stores/Material offered should strictly confirm to our specifications. Deviations if any, should be clearly indicated by the tenderer in their quotation. The tenderer should indicate the Make’ Type number of the Stores offered and provide catalogues, technical literature and samples, wherever necessary along with the quotations. Test Certificates, wherever necessary, should be forwarded along with supplies. Whenever options are called for in our specifications, the tenderer should address all such options. Whenever specifically mentioned by us, the tenderer could suggest changes to specification with appropriate reasons for the same. Even in such cases, the tenderer should state why he cannot meet our specifications and why he is suggesting the changes.  11.GUARANTEE: The stores/Material offered should be guaranteed for a minimum period of 12 months against defective material, design, operation or manufacture. For defects noticed during the guarantee period, replacement rectification should be arranged free of cost within a reasonable period of such notification. In case where our specifications called for a guarantee period of more than 12 months specifically, then such a period shall apply.  12.ARBITRATION: In the event of any question, dispute or difference arising under these conditions or any condition in the Purchase Order or in connection with this contract, (except as to any matters the decision of which is specially provided for by these conditions) the same shall be referred to the sole arbitration of the XDLINX Space Labs Private Limited or of some other person appointed by XDLINX Space Labs Private Limited. The award of the Arbitrator shall be final and binding on the parties of this contract/Order and other procedures of Arbitration shall be followed as per the Prevailing Arbitration and Reconciliation ACT 1996 and further Amendments.  13.Successful tenderer will have to furnish in the form a Bank Guarantee or in any other form as called for by the Purchaser towards adequate security for the materials / properly provided by the Purchaser for the one execution of the contract.  14.PACKING & FORWARDING: The Contractor will be held responsible for the stores being sufficiently and properly packed for transport by rail, road, sea or air, to withstand transit hazards and ensure safe arrival at the destination. The packing and Marking of packages shall be done by and at the expenses of the Contractor.  15.Advance Payment: Wherever advance payment is requested, Necessary security in terms of Bank guarantee / Corporate Guarantee / Indemnity bond should be furnished.  16.Liquidated Damages: In all cases, where advance payment is involved and where delivery is critical Liquidated Damages clause will be applicable at 0.5% per week or part thereof subject to a maximum of 10% of total order value.  17.Performance Bank Guarantee: Wherever called for Performance Bank Guarantee for 10% of the order value should be furnished covering the warranty period.  18.The delivery period mentioned in the tender enquiry, IF ANY, is with the stipulation that no credit will be given for earlier deliveries and offers with delivery beyond the period will be treated as unresponsive.  19.The purchaser will have the option to consider more than one source of supply and final orders will be given accordingly.  20.Non-acceptance of any conditions wherever called for related to Guarantee/warranty Performance Bank Guarantee; Liquidated damages are liable for disqualification."}]', true, '2026-02-10 09:14:58.023577+00', 'system@spacelinx.local', '2026-02-10 09:27:07.905673+00', 'system@spacelinx.local', 'Standard Terms and Conditions', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
